/* PLAY-19 (владелец, 27 ноября): механики бега нет, поэтому дистанцию Classic передаём «сближением». Если в отряде только бойцы дальнего боя
   (маг, жрец, чернокнижник, охотник, друид вне облика), враг ближнего боя первый свой ход тратит на подход — как в Classic, где кастер успевал
   2–3 заклинания, пока враг бежал. Замедление или корни от героя во время подхода продлевают его на один ход (один раз). Враги-заклинатели
   (ИИ mystic, hexer) и манекены не подходят. В отряде с бойцом ближнего боя или с питомцем враги сразу заняты им (как танк в Classic). APPROACH.turns для симуляторов. */
const APPROACH = { turns: 1, skipAi: ['mystic', 'hexer', 'dummy', 'tankdummy', 'srcdummy'] };
function rangedHero(h) {
  if (h.cls === 'mage' || h.cls === 'priest' || h.cls === 'warlock' || h.cls === 'hunter') return true;
  return h.cls === 'druid' && (h.neutralTraining || h.spec === 'balance' || h.spec === 'resto');
}
function enemyApproach(st, e) {
  if (e.approach === undefined) {
    const party = alive(st.heroes).filter(function (h) { return !h.pet && !h.dummy; });
    const meleePet = (st.pets || []).some(function (p) { return p.hp > 0 && !p.gone; }); /* с питомцем сближения нет: в Classic враг шёл на питомца (у чернокнижника с 10 — Демон Бездны) */
    e.approach = APPROACH.turns > 0 && APPROACH.skipAi.indexOf(e.ai) === -1 && party.length && !meleePet && party.every(rangedHero) ? APPROACH.turns : 0;
  }
  if (!(e.approach > 0)) return false;
  e.approach--;
  if (!e.approachSlowed && e.effects.some(function (f) { return (f.kind === 'slow' || f.kind === 'root') && f.src && String(f.src).charAt(0) === 'h'; })) { e.approachSlowed = true; e.approach++; }
  emit(st, { t: 'eskill', src: e.id, id: 'approach', name: 'Сближение', icon: '🏃' });
  log(st, e.name + ' сближается', 'info');
  return true;
}
