   маг «Ледяной доспех» (1), чернокнижник «Демоническая кожа» (1), друид «Знак дикой природы» (1) — броня; жрец «Слово силы: Щит» (6) — поглощение. */
st.heroes.forEach(function (h) {
  if (!h.neutralTraining) return;
  const w = TRAINING_WARDS[h.cls]; if (!w || h.level < w.level) return;
  if (w.armor) h.armor = Math.min(0.75, (h.armor || 0) + w.armor);
  if (w.shield) h.effects.push({ kind: 'shield', amt: Math.round(h.maxHp * w.shield), turns: 999, src: h.id, name: w.name, icon: w.icon });
  else h.effects.push({ kind: 'ward', turns: 999, src: h.id, name: w.name, icon: w.icon });
});

